 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    row_lines = [r for r in range(h) if len(set(grid[r])) == 1]
    col_lines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    # The full-width/full-height uniform lines form the grid separators.
    row_groups = []
    start = 0
    for r in row_lines:
        if start < r:
            row_groups.append((start, r))
        start = r + 1
    if start < h:
        row_groups.append((start, h))
    col_groups = []
    start = 0
    for c in col_lines:
        if start < c:
            col_groups.append((start, c))
        start = c + 1
    if start < w:
        col_groups.append((start, w))

    separator_colors = {grid[r][0] for r in row_lines}
    separator_colors.update(grid[0][c] for c in col_lines)
    counts = Counter(
        grid[r][c]
        for r0, r1 in row_groups
        for c0, c1 in col_groups
        for r in range(r0, r1)
        for c in range(c0, c1)
        if grid[r][c] not in separator_colors
    )
    background = counts.most_common(1)[0][0]
    marker_candidates = [color for color in counts if color != background]
    marker = marker_candidates[0] if marker_candidates else None

    out = []
    for r0, r1 in row_groups:
        row = []
        for c0, c1 in col_groups:
            n = sum(
                grid[r][c] == marker
                for r in range(r0, r1)
                for c in range(c0, c1)
            ) if marker is not None else 0
            row.append(1 if n > 1 else background)
        out.append(row)
    return out


if __name__ == '__main__':
    demo = [
        [3,3,9,3,5,9,3,5], [3,5,9,3,3,9,3,3], [9]*8,
        [5,3,9,3,3,9,3,3], [3,3,9,3,5,9,5,3], [9]*8,
        [3,3,9,3,3,9,5,3], [5,3,9,5,3,9,3,5],
    ]
    assert transform(demo) == [[3,3,3],[3,3,3],[3,3,1]]
