        [3]*11, [0,0,0,3,0,0,0,3,0,5,0], [0,0,0,3,0,0,0,3,0,0,0], [0,0,5,3,0,5,0,3,5,0,0],
        [3]*11, [0,5,0,3,0,0,5,3,0,0,0], [0,0,0,3,0,0,0,3,0,0,0], [0,0,0,3,0,0,0,3,0,5,5],
    ]
    print(transform(test))
    assert transform(test) == [[1,0,0],[0,0,1],[0,0,1]]
    print('demo and test checks passed')
